// 1. Recuperar variables
var limite = flow.get("limite") || 20;
var fechaSeleccionada = flow.get("fecha"); // Viene del Date Picker (timestamp)

msg.limit = parseInt(limite);

// 2. Ordenar
// IMPORTANTE: Como tu fecha es texto ("05/11/2025"), no se puede ordenar cronológicamente bien.
// TRUCO: Usamos "_id" de MongoDB, que internamente ya contiene la fecha de creación y siempre está ordenado.
msg.sort = { "_id": -1 };

// 3. Construir la consulta
if (fechaSeleccionada) {
    // Convertimos el timestamp del selector a un objeto Fecha
    var dateObj = new Date(fechaSeleccionada);

    // Convertimos esa fecha A TEXTO, exactamente igual que como la guardaste.
    // Usamos toLocaleDateString() para que coincida con tu nodo de guardar.
    var fechaString = dateObj.toLocaleDateString();

    // La consulta busca que el campo "date" sea IGUAL a ese texto
    msg.payload = {
        "date": fechaString
    };
} else {
    // Si no hay fecha, busca todo
    msg.payload = {};
}

return msg;

