// 1. Configurar fechas (últimos 30 días)
var diasAtras = 30;
var fechaInicio = new Date();
fechaInicio.setDate(fechaInicio.getDate() - diasAtras);

// 2. Construir la Query corregida para tu estructura
msg.payload = {
    // Buscamos dentro del objeto 'payload'
    "payload.fecha": { 
        "$gte": fechaInicio 
    },
    "$expr": {
        "$and": [
            // El campo está anidado en payload.fecha
            { "$gte": [{ "$hour": "$payload.fecha" }, 13] },
            { "$lte": [{ "$hour": "$payload.fecha" }, 14] }
        ]
    }
};

// 3. Proyección: Traemos el objeto payload entero para no liarnos
msg.projection = { payload: 1 };

// 4. Ordenar
msg.sort = { "payload.fecha": 1 };

return msg;

var fotosLimpias = [];

// Verificamos que Mongo haya devuelto algo
if (msg.payload && Array.isArray(msg.payload)) {
    msg.payload.forEach(function(item) {
        // AQUI ESTABA LA CLAVE: 
        // La imagen está en item.payload.imagen_data
        if (item.payload && item.payload.imagen_data) {
            fotosLimpias.push(item.payload.imagen_data);
        }
    });
}

msg.payload = fotosLimpias;
return msg;

var humedad = flow.get("HumActual") 
