var TempActual = msg.payload.temperatura;
var HumActual = msg.payload.humedad_aire;
var HumSueloActual = msg.payload.humedad_suelo;
var Luminosidad = msg.payload.luminosidad;

// Guardamos este valor en una variable de flujo llamada "umbralTemperatura"
flow.set("TempActual", TempActual);
flow.set("LuminosidadActual", Luminosidad);
flow.set("HumActual", HumActual);
flow.set("HumSueloActual", HumSueloActual);

// (Opcional) Pasamos el mensaje por si quieres poner un debug después
return msg;

// Obtenemos los datos de entrada (el array de MongoDB)
var datos = msg.payload;

// Preparamos arrays vacíos para cada tipo de dato
var dataTemperatura = [];
var dataHumedadAire = [];
var dataLuminosidad = [];
var dataHumedadSuelo = [];

// Recorremos cada lectura guardada
datos.forEach(function (registro) {

    // 1. CREAR EL TIMESTAMP
    // Tu formato es "MM/DD/YYYY" y "HH:MM:SS PM/AM"
    // Concatenamos fecha y hora para crear un objeto Date válido
    var fechaString = registro.date + " " + registro.time;
    var timestamp = new Date(fechaString).getTime(); // Convertimos a milisegundos

    // 2. LLENAR LOS ARRAYS
    // El formato standard para charts históricos es {x: tiempo, y: valor}

    if (registro.temperatura !== undefined) {
        dataTemperatura.push({ x: timestamp, y: registro.temperatura });
    }

    if (registro.humedad_aire !== undefined) {
        dataHumedadAire.push({ x: timestamp, y: registro.humedad_aire });
    }

    if (registro.luminosidad !== undefined) {
        dataLuminosidad.push({ x: timestamp, y: registro.luminosidad });
    }

    if (registro.humedad_suelo !== undefined) {
        dataHumedadSuelo.push({ x: timestamp, y: registro.humedad_suelo });
    }
});

// 3. PREPARAR LOS MENSAJES DE SALIDA
// Creamos un mensaje individual para cada gráfica.
// Nota: Enviamos el array completo para que la gráfica pinte todo el historial de golpe.

var msgTemp = { topic: "Temperatura", payload: [{ series: ["Temperatura"], data: [dataTemperatura] }] };
var msgHumA = { topic: "Humedad Aire", payload: [{ series: ["Humedad Aire"], data: [dataHumedadAire] }] };
var msgLum = { topic: "Luminosidad", payload: [{ series: ["Luminosidad"], data: [dataLuminosidad] }] };
var msgHumS = { topic: "Humedad Suelo", payload: [{ series: ["Humedad Suelo"], data: [dataHumedadSuelo] }] };

// Retornamos 4 salidas (asegúrate de configurar el nodo para tener 4 salidas)
return [msgTemp, msgLum, msgHumA, msgHumS];

