};
return msg;

flow.set("chatId", msg.payload.chatId);

var suelo = global.get("suelo") || 0;

if (suelo > 55) {
    flow.set("esperando", "riego");
    msg.payload = {
        chatId: msg.payload.chatId,
        type: "message",
        content: `⚠️ Suelo ${suelo}% (>55%). ¿Estas seguro de que quieres Regar?`,
        options: {
            reply_markup: {
                inline_keyboard: [
                    [{ text: "✅ Sí", callback_data: "riego_si" }],
                    [{ text: "❌ No", callback_data: "riego_no" }]
                ]
            }
        }
    };
    return msg;
}

msg.payload = {
    _accion: "regar",
    chatId: msg.payload.chatId
};
return msg;

flow.set("chatId", msg.payload.chatId);

var hum = global.get("humedad") || 0;

if (hum < 73) {
    flow.set("esperando", "vent");
    msg.payload = {
        chatId: msg.payload.chatId,
        type: "message",
        content: `⚠️ Humedad ${hum}% (<73%) ¿Estas seguro de que quieres Ventilar?`,
        options: {
            reply_markup: {
                inline_keyboard: [
                    [{ text: "✅ Sí", callback_data: "vent_si" }],
                    [{ text: "❌ No", callback_data: "vent_no" }]
                ]
            }
        }
    };
    return msg;
}

msg.payload = {
    _accion: "ventilar",
    chatId: msg.payload.chatId
};
return msg;

var esperando = flow.get("esperando");   // "riego" o "vent"
var chatId = flow.get("chatId");

// ⚠️ GUARDAMOS EL DATO DEL BOTÓN ANTES DE MODIFICAR msg.payload
var data = msg.payload.content;

// ===== ACK SIEMPRE =====
var ack = {
    payload: {
        type: "callback_query",
        callbackQueryId: msg.payload.callbackQueryId
    }
};

// ===== MENSAJE CANCELADO =====
var cancelMsg = {
    payload: {
        chatId: chatId,
        type: "message",
        content: "❌ Acción cancelada"
    }
};

// ===== RIEGO =====
if (esperando === "riego") {
    flow.set("esperando", null);

    if (data === "riego_si") {
        return [
            {
                topic: "II11/actuadores/regar",
                payload: "1",
                chatId: chatId
            },
            null,
            ack,
            null
        ];
    }

    // NO
    return [
        null,
        null,
        ack,
        cancelMsg
    ];
}

// ===== VENTILACIÓN =====
if (esperando === "vent") {
    flow.set("esperando", null);

    if (data === "vent_si") {
        return [
            null,
            {
                topic: "II11/actuadores/ventilar",
                payload: "1",
                chatId: chatId
            },
            ack,
            null
        ];
    }

    // NO
    return [
        null,
        null,
        ack,
        cancelMsg
    ];
}

// Fallback
return [null, null, ack, null];

